const sample = {
  "demo": true,
  "name": "Leila Haddad",
  "email": "leila@example.com",
  "role": "Automation engineer",
  "years": 5,
  "workAuth": true,
  "resumeText": "Five years building JavaScript services, SQL reporting, and n8n workflows for HubSpot teams."
};
const incoming = $input.first()?.json ?? {};
const provided = Object.keys(incoming).filter((key) => incoming[key] !== undefined && incoming[key] !== null && incoming[key] !== '');
const base = provided.length ? { ...sample, ...incoming } : { ...sample };
const flag = incoming.demo;
base.demo = !(flag === false || flag === 'false' || flag === 0 || flag === '0');
return [{ json: base }];

const item = $input.first().json;
const produced = (() => {

const text = String(item.resumeText || item.cv || '').toLowerCase();
const must = ['javascript', 'sql'];
const nice = ['n8n', 'hubspot'];
const haveMust = must.filter((skill) => text.includes(skill));
const haveNice = nice.filter((skill) => text.includes(skill));
const experience = Number(item.years || (text.match(/(\d+)\s+\+?\s*years/) || [])[1] || 0);
let score = haveMust.length * 20 + haveNice.length * 8;
if (experience >= 3) score += 15;
if (item.workAuth === false) score -= 25;
score = Math.max(0, Math.min(100, score));
const route = haveMust.length < Math.ceil(must.length / 2) ? 'reject' : score >= 70 ? 'screen' : 'hold';
const record = {
  name: item.name || 'Candidate',
  email: item.email || '',
  role: item.role || 'Open role',
  score,
  route,
  haveMust: haveMust.join(', '),
  haveNice: haveNice.join(', '),
  experience,
  title: (item.name || 'Candidate') + ' — ' + (item.role || 'role'),
};
return {
  summary: record.name + ' scored ' + score + ' for ' + record.role + ' (' + route + ').',
  route,
  record,
  slackText: route.toUpperCase() + ' ' + record.name + ' (' + score + ') for ' + record.role,
  actions: [{ app: 'ATS', operation: route, payload: record }],
};

})();
if (!produced || typeof produced.summary !== 'string' || !produced.summary.trim()) {
  throw new Error('Apply rules must return a summary string');
}
return [{
  json: {
    ...item,
    ...produced,
    demo: item.demo !== false,
  },
}];

const item = $input.first().json;
return [{
  json: {
    demo: true,
    status: 'demo_ready',
    workflow: 'offer-letter-data-pack',
    summary: item.summary,
    route: item.route ?? null,
    record: item.record ?? {},
    actions: item.actions ?? [],
    slackText: item.slackText ?? item.summary,
    notes: 'Demo mode did not call external apps. Send {"demo": false} after placeholder credentials are replaced.',
  },
}];
